import type { FastifyRequest } from 'fastify';
import type { Tx as Tx0 } from '../db.js';
/** Y01: birim yetkisi ile birlikte komut makbuzunun kaynak/kapsam bilgisi de yazılır; makbuz tekrarı bu bilgiye göre yeniden yetkilendirilir */
const requireUnitProfileR = async (req: FastifyRequest, tx: Tx0, p: Principal & { tenantId: string }, unitId: string, ...allowed: Profile[]) => { const r = await requireUnitProfile0(tx, p, unitId, ...allowed); req.idempotencyResource = { scope: 'unit', unitId, profiles: allowed }; return r; };
import { config } from '../config.js';
import { normTxt } from '../textnorm.js';
