  app.post('/api/t/:tid/targets/:ltid/followup/review', { schema: { body: { type: 'object', required: ['cycleId', 'decision', 'comparabilityVersion', 'resultVersion'], properties: { cycleId: { type: 'string', format: 'uuid' }, decision: { type: 'string', enum: ['comparable', 'comparable_labeled', 'not_comparable'] }, comparabilityVersion: { type: 'string', maxLength: 120 }, resultVersion: { type: 'string', pattern: '^R\\d+$' } }, additionalProperties: false } } }, async req => { const p = await requireTenant(req, (req.params as { tid: string }).tid); const { ltid } = req.params as { ltid: string }; const b = req.body as { cycleId: string; decision: 'comparable' | 'comparable_labeled' | 'not_comparable'; comparabilityVersion: string; resultVersion: string }; return withContext(dbCtx(p), async tx => { const person = (await tx.query('SELECT person_id FROM membership WHERE tenant_id = $1 AND user_id = $2', [p.tenantId, p.userId])).rows[0]?.person_id ?? p.userId; const rev = Number(String(b.resultVersion).replace(/^R/, '')); if (!Number.isInteger(rev)) throw new HttpError(400, 'invalid_result_version'); const own = (await tx.query('SELECT unit_id, status FROM local_target WHERE tenant_id = $1 AND id = $2', [p.tenantId, ltid])).rows[0]; if (!own) throw new HttpError(404, 'not_found'); await requireUnitProfileR(req, tx, p, own.unit_id, 'HR_ADMIN', 'HR_PARTNER'); if (own.status === 'under_review') throw new HttpError(409, 'target_under_review', 'İncelemedeki hedef için takip kararı verilemez'); const cur = (await tx.query('SELECT id, comparability_version, result_revision, followup_result_id, baseline_result_id, target_version FROM outcome_assessment WHERE tenant_id = $1 AND local_target_id = $2 AND followup_cycle_id = $3', [p.tenantId, ltid, b.cycleId])).rows[0]; if (!cur) throw new HttpError(409, 'assessment_missing', 'Önce takip değerlendirmesi çalıştırılmalı'); if (cur.comparability_version !== b.comparabilityVersion || `R${cur.result_revision}` !== b.resultVersion) throw new HttpError(409, 'assessment_stale', `Onay canlı değerlendirmeyle uyuşmuyor (sürüm ${cur.comparability_version}, R${cur.result_revision}); yeniden değerlendirin`); const live = (await tx.query('SELECT r.id, r.revision, t.version, t.baseline_result_id FROM local_target t JOIN survey_cycle c ON c.tenant_id = t.tenant_id AND c.id = $3 JOIN result r ON r.tenant_id = t.tenant_id AND r.cycle_id = c.id AND r.import_batch_id = c.active_batch_id AND r.unit_id = t.unit_id AND r.metric_code = t.item_code || $4 WHERE t.tenant_id = $1 AND t.id = $2', [p.tenantId, ltid, b.cycleId, '_TB'])).rows[0]; if (!live || live.id !== cur.followup_result_id || Number(live.version) !== Number(cur.target_version) || live.baseline_result_id !== cur.baseline_result_id) throw new HttpError(409, 'assessment_stale', 'Takip sonucu, hedef ya da başlangıç değerlendirmeden sonra değişti; yeniden değerlendirin'); /* V15: canlı aktif sonuç + hedef sürümü + başlangıç */ /* N25 */ const r = await tx.query('INSERT INTO comparability_review (tenant_id, local_target_id, followup_cycle_id, decision, comparability_version, result_revision, reviewed_by, assessment_id) VALUES ($1,$2,$3,$4,$5,$6,$7,$8) RETURNING id', [p.tenantId, ltid, b.cycleId, b.decision, b.comparabilityVersion, rev, person, cur.id]); await audit(tx, p, 'comparability_review', r.rows[0].id, 'create', null, { targetId: ltid, cycleId: b.cycleId, decision: b.decision, comparabilityVersion: b.comparabilityVersion, resultVersion: b.resultVersion }); return { id: r.rows[0].id, targetId: ltid }; }); });
