      if (unitId) await requireUnitProfileR(req, tx, p, unitId, 'HR_ADMIN', 'HR_PARTNER', 'REGION_MANAGER', 'UNIT_MANAGER', 'ACTION_OWNER'); else { requireProfile(p, 'HR_ADMIN', 'HR_PARTNER'); req.idempotencyResource = { scope: 'tenant', profiles: ['HR_ADMIN', 'HR_PARTNER'] }; }
      const existing = (await tx.query('SELECT id, sla_due_at FROM attention_item WHERE tenant_id = $1 AND dedupe_key = $2', [p.tenantId, dk])).rows[0];
      if (existing) { await tx.query('UPDATE attention_item SET state = $3, sla_due_at = $4 WHERE tenant_id = $1 AND id = $2', [p.tenantId, existing.id, 'snoozed', b.until]); } else await tx.query("INSERT INTO attention_item (tenant_id, audience_person_id, item_type, severity, entity_type, entity_id, dedupe_key, state, sla_due_at) VALUES ($1,$2,'snooze','info','attention',$2,$3,'snoozed',$4)", [p.tenantId, p.userId, dk, b.until]);
      await audit(tx, p, 'attention_item', null, 'snooze', existing ? { until: existing.sla_due_at } : null, { key: dk, until: b.until, unitId }, undefined);
